def transform(grid):
    # Marker is the conspicuous connected component of the unique color that forms
    # a long line/border motif; recolor the nearest non-background object to it.
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    bg = max(set(v for row in g for v in row), key=lambda c: sum(row.count(c) for row in g))
    seen = set()
    comps = []
    for r in range(h):
        for c in range(w):
            color = g[r][c]
            if color == bg or (r,c) in seen: continue
            q=deque([(r,c)]); seen.add((r,c)); cells=[]
            while q:
                x,y=q.popleft(); cells.append((x,y))
                for nx,ny in ((x-1,y),(x+1,y),(x,y-1),(x,y+1)):
                    if 0<=nx<h and 0<=ny<w and (nx,ny) not in seen and g[nx][ny]==color:
                        seen.add((nx,ny)); q.append((nx,ny))
            comps.append((color,cells))
    # In this task the marker is the largest connected component of its rare color;
    # select the nearest other component and recolor it to the marker color.
    marker=max(comps, key=lambda x: len(x[1]))
    mc, m_cells=marker
    def dist(a,b): return min(abs(x-u)+abs(y-v) for x,y in a for u,v in b)
    others=[x for x in comps if x is not marker]
    target=min(others,key=lambda x:dist(m_cells,x[1]))
    for r,c in target[1]: g[r][c]=mc
    return g

